<span class="line"><span style="color:#61AFEF;">snap</span><span style="color:#98C379;"> install</span><span style="color:#98C379;"> code</span><span style="color:#D19A66;"> --classic</span><span style="color:#7F848E;font-style:italic;">   # --classic 允许访问系统文件</span></span>
